    "alert_id": "EX2_MONITOR_GAP_003",
    "title": "Missing Routine Creatinine Monitoring",
    "message": "Guidelines advise checking creatinine in patients on TDF during intercurrent illness with dehydration. The patient was on TDF for 2 years, with the last creatinine check 375 days ago. Routine monitoring prior to this acute illness was overdue. The current severe dehydration necessitated the check, revealing AKI.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Ensure creatinine is monitored during this admission and schedule regular renal function tests per ART monitoring guidelines after recovery.",
    "citations": [
      {"page_number": 40, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p40_c2"}
    ]
  }
